-- Apply only after the PR is merged and all media return HTTP 200 in production.
BEGIN;
DO $publish$
DECLARE
 payload jsonb := $content$[{"language":"es","slug":"pernil-de-cerdo-al-horno","title":"Pernil de cerdo al horno colombiano y jugoso","seo":{"title":"Pernil de cerdo al horno colombiano y jugoso","description":"Prepara pernil de cerdo al horno al estilo colombiano: adobo desde la víspera, cocción lenta y acabado dorado, con temperatura interna y reposo.","faq":[{"q":"¿Puedo adobarlo durante 24 horas?","a":"Sí. Mantén la pieza tapada a 4 °C o menos y hornea antes de completar 24 horas de adobo."},{"q":"¿Sirve un pernil con hueso?","a":"Sí, pero el peso útil y el tiempo cambian. Esta receta está calculada para 3 kg sin hueso; comprueba varios puntos sin tocar el hueso."},{"q":"¿Cómo evito que quede seco?","a":"Conserva líquido en la bandeja, hornea bien tapado y mide la temperatura. Respeta los 30 minutos de reposo antes de cortar."}],"image_alt":"Pernil de cerdo al horno colombiano y jugoso","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-16x9.webp"],"additional_time_minutes":750},"summary":"Un pernil de diciembre para compartir: pierna de cerdo adobada con cítricos, ajo, cebolla y comino desde la víspera. El horneado cubierto conserva los jugos y el golpe final de calor dora la superficie.","ingredients":[{"amount":"3000","unit":"g","name":"pierna de cerdo deshuesada, sin piel y con una capa fina de grasa, en una sola pieza sin enrollar"},{"amount":"200","unit":"g","name":"cebolla blanca pelada"},{"amount":"40","unit":"g","name":"ajo pelado"},{"amount":"300","unit":"ml","name":"jugo de naranja recién exprimido"},{"amount":"60","unit":"ml","name":"jugo de limón recién exprimido"},{"amount":"30","unit":"g","name":"aceite vegetal"},{"amount":"30","unit":"g","name":"sal"},{"amount":"4","unit":"g","name":"comino molido"},{"amount":"3","unit":"g","name":"orégano seco"},{"amount":"2","unit":"g","name":"pimienta negra molida"},{"amount":"2","unit":"unidad","name":"hojas de laurel secas"},{"amount":"400","unit":"ml","name":"agua para la bandeja"}],"steps":[{"title":"Seca el pernil","content":"Seca los 3000 g de pernil con papel de cocina, sin lavarlo."},{"title":"Licúa el adobo","content":"Licúa los 200 g de cebolla, 40 g de ajo, 300 ml de naranja, 60 ml de limón, 30 g de aceite, 30 g de sal, 4 g de comino, 3 g de orégano y 2 g de pimienta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-02.webp","image_alt":"Licúa el adobo"},{"title":"Adoba el pernil","content":"Unta toda la pieza con el adobo dentro de un recipiente hondo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-03.webp","image_alt":"Adoba el pernil"},{"title":"Añade el laurel","content":"Coloca las 2 hojas de laurel junto al pernil."},{"title":"Tapa el recipiente","content":"Cierra el recipiente para evitar derrames y contacto con otros alimentos."},{"title":"Refrigera","content":"Deja el pernil en la nevera a 4 °C o menos durante 12 horas."},{"title":"Precalienta el horno","content":"Calienta el horno a 165 °C con calor arriba y abajo, sin ventilador."},{"title":"Coloca el pernil","content":"Pasa el pernil y todo el adobo a una bandeja honda, con la grasa hacia arriba."},{"title":"Añade agua","content":"Vierte los 400 ml de agua alrededor de la carne."},{"title":"Cubre la bandeja","content":"Cierra la bandeja firmemente con papel de aluminio apto para horno.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-10.webp","image_alt":"Cubre la bandeja"},{"title":"Hornea lentamente","content":"Hornea tapado a 165 °C durante 3 horas; mantén algo de líquido en el fondo con agua caliente adicional si hiciera falta."},{"title":"Comprueba el centro","content":"Mide la parte más gruesa sin tocar la bandeja: debe alcanzar al menos 63 °C antes del dorado; si no llega, continúa tapado en tandas de 15 minutos, hasta 1 hora adicional orientativa."},{"title":"Destapa","content":"Retira el aluminio con cuidado del vapor."},{"title":"Baña la carne","content":"Riega la superficie con los jugos calientes de la bandeja."},{"title":"Sube la temperatura","content":"Ajusta el horno a 220 °C."},{"title":"Dora el pernil","content":"Hornea destapado durante 20–30 minutos, hasta que la superficie quede dorada; cubre solo las zonas que se oscurezcan demasiado.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-16.webp","image_alt":"Dora el pernil"},{"title":"Verifica la temperatura","content":"Comprueba varios puntos gruesos con termómetro: busca 68–72 °C para esta preparación; el mínimo seguro del cerdo entero es 63 °C con al menos 3 minutos de reposo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-17.webp","image_alt":"Verifica la temperatura"},{"title":"Pasa a una tabla","content":"Traslada el pernil a una tabla con canal para recoger los jugos."},{"title":"Cubre suavemente","content":"Coloca aluminio suelto sobre el pernil, sin sellarlo."},{"title":"Deja reposar","content":"Deja reposar 30 minutos antes de cortar."},{"title":"Retira el laurel","content":"Retira las 2 hojas de laurel de los jugos."},{"title":"Desgrasa los jugos","content":"Retira la grasa superficial de los jugos de la bandeja."},{"title":"Hierve la salsa","content":"Hierve los jugos desgrasados en una olla pequeña durante 5 minutos."},{"title":"Corta el pernil","content":"Corta 12 porciones en lonchas atravesando la dirección de las fibras.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-24.webp","image_alt":"Corta el pernil"},{"title":"Sirve","content":"Sirve el pernil con su salsa caliente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","image_alt":"Pernil de cerdo al horno colombiano y jugoso"}],"notes":"<p>Los tiempos corresponden a una pieza entera deshuesada de 3 kg y unos 12–14 cm de grosor, sin piel ni relleno. Prevé 3 h 20 min–4 h 30 min de horno; el termómetro decide el final. No pinches ni inyectes la carne para este método. El mínimo de seguridad de 63 °C más 3 minutos de reposo no obliga a cocinarla hasta 90 °C: esta versión se corta en lonchas. El dorado queda en la grasa y la carne; no se busca chicharrón porque no lleva piel. El adobo que tocó carne cruda se cocina con el pernil y después hierve en la salsa. Refrigera las sobras en recipientes poco profundos antes de 2 horas y consúmelas en 3–4 días; recalienta hasta 74 °C. Puedes congelarlas hasta 2 meses.</p>","author":"Néstor Bastidas","category":"Platos principales","cuisine":"Colombiana","difficulty":"Intermedia","servings":12,"public_path":"/es/receta/pernil-de-cerdo-al-horno","prep_time_minutes":25,"cook_time_minutes":245,"marinate_time_minutes":720,"rest_time_minutes":30,"total_time_minutes":1020,"nutrition":{"calories":661.1,"protein_g":44.3,"carbs_g":6.1,"fat_g":49.9,"serving_size":"1 de 12 porciones con salsa","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Suma de nutrientes de ingredientes crudos según perfiles USDA, dividida entre las porciones; los zumos se aproximan a 1 g por ml.","note":"Estimación para 1 de 12 porciones, con reparto de toda la salsa y sin acompañamientos. Usa un perfil de pierna con carne y grasa; cuenta toda la grasa y el adobo, sin descontar lo retirado de la bandeja, por lo que puede sobreestimar la ración servida. No incluye las hojas de laurel."},"excerpt":"Un pernil de diciembre para compartir: pierna de cerdo adobada con cítricos, ajo, cebolla y comino desde la víspera. El horneado cubierto conserva los jugos y el golpe final de calor dora la superficie.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","course":"Platos principales","keywords":["Pernil de cerdo al horno colombiano y jugoso"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/ingredientes.webp","alt":"Pernil de cerdo al horno colombiano y jugoso"}]},{"language":"en","slug":"colombian-roast-pork-leg-pernil","title":"Colombian Roast Pork Leg (Pernil)","seo":{"title":"Colombian Roast Pork Leg (Pernil)","description":"Make Colombian pernil with an overnight citrus and garlic marinade, slow oven roasting and a golden finish, with clear timing and internal temperatures.","faq":[{"q":"Can I marinate it for 24 hours?","a":"Yes. Keep it covered at 4 °C or below and roast before the marinade time exceeds 24 hours."},{"q":"Can I use a bone-in leg?","a":"Yes, but edible yield and timing change. This recipe is calculated for 3 kg boneless pork; check several points without touching the bone."},{"q":"How do I keep it juicy?","a":"Keep liquid in the pan, cover tightly during the slow roast and check the temperature. Rest for the full 30 minutes before slicing."}],"image_alt":"Colombian Roast Pork Leg (Pernil)","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-16x9.webp"],"additional_time_minutes":750},"summary":"A Colombian December centerpiece: pork leg marinated overnight with citrus, garlic, onion and cumin. Covered roasting keeps the meat juicy before a final blast of heat browns the outside.","ingredients":[{"amount":"3000","unit":"g","name":"boneless skinless pork leg with a thin fat cap, one whole piece, not rolled"},{"amount":"200","unit":"g","name":"peeled white onion"},{"amount":"40","unit":"g","name":"peeled garlic"},{"amount":"300","unit":"ml","name":"freshly squeezed orange juice"},{"amount":"60","unit":"ml","name":"freshly squeezed lime juice"},{"amount":"30","unit":"g","name":"vegetable oil"},{"amount":"30","unit":"g","name":"salt"},{"amount":"4","unit":"g","name":"ground cumin"},{"amount":"3","unit":"g","name":"dried oregano"},{"amount":"2","unit":"g","name":"ground black pepper"},{"amount":"2","unit":"piece","name":"dried bay leaves"},{"amount":"400","unit":"ml","name":"water for the roasting pan"}],"steps":[{"title":"Dry the pork","content":"Pat the 3000 g pork leg dry with kitchen paper; do not rinse it."},{"title":"Blend the marinade","content":"Blend the 200 g onion, 40 g garlic, 300 ml orange juice, 60 ml lime juice, 30 g oil, 30 g salt, 4 g cumin, 3 g oregano and 2 g pepper.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-02.webp","image_alt":"Blend the marinade"},{"title":"Coat the pork","content":"Coat the whole pork leg with the marinade in a deep container.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-03.webp","image_alt":"Coat the pork"},{"title":"Add the bay leaves","content":"Place the 2 bay leaves beside the pork."},{"title":"Cover the container","content":"Seal the container to prevent leaks and contact with other food."},{"title":"Chill","content":"Refrigerate the pork at 4 °C or below for 12 hours."},{"title":"Preheat the oven","content":"Heat a conventional oven to 165 °C, without fan assistance."},{"title":"Transfer to the pan","content":"Place the pork and all the marinade in a deep roasting pan, fat side up."},{"title":"Add water","content":"Pour the 400 ml water around the meat."},{"title":"Cover the pan","content":"Seal the pan tightly with oven-safe foil.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-10.webp","image_alt":"Cover the pan"},{"title":"Slow-roast","content":"Roast covered at 165 °C for 3 hours; keep a little liquid in the pan, adding extra hot water if needed."},{"title":"Check the center","content":"Probe the thickest part without touching the pan: it must reach at least 63 °C before browning; if needed, roast covered in further 15-minute intervals, allowing roughly up to 1 extra hour."},{"title":"Uncover","content":"Carefully remove the foil, avoiding the steam."},{"title":"Baste","content":"Spoon the hot pan juices over the pork."},{"title":"Turn up the heat","content":"Increase the oven temperature to 220 °C."},{"title":"Brown the pork","content":"Roast uncovered for 20–30 minutes until golden; shield only areas that darken too quickly.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-16.webp","image_alt":"Brown the pork"},{"title":"Check the temperature","content":"Probe several thick areas: aim for 68–72 °C for this recipe; whole pork has a safe minimum of 63 °C followed by at least 3 minutes of rest.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-17.webp","image_alt":"Check the temperature"},{"title":"Move to a board","content":"Transfer the pork to a carving board with a juice groove."},{"title":"Tent loosely","content":"Lay foil loosely over the pork without sealing it."},{"title":"Rest","content":"Rest for 30 minutes before carving."},{"title":"Remove the bay leaves","content":"Remove the 2 bay leaves from the pan juices."},{"title":"Skim the juices","content":"Skim the fat from the pan juices."},{"title":"Boil the sauce","content":"Boil the skimmed juices in a small saucepan for 5 minutes."},{"title":"Carve","content":"Cut into 12 portions, slicing across the grain.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-24.webp","image_alt":"Carve"},{"title":"Serve","content":"Serve the pork with its hot sauce.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","image_alt":"Colombian Roast Pork Leg (Pernil)"}],"notes":"<p>Timing is for a whole, unrolled 3 kg boneless leg, around 12–14 cm thick, without skin or stuffing. Allow 3 hours 20 minutes–4 hours 30 minutes in the oven; use a thermometer to judge doneness. Do not pierce or inject the meat for this method. The 63 °C minimum plus 3 minutes of rest is a safety threshold; this sliced roast does not need to reach 90 °C. With no skin, the finish is browned meat and fat rather than crackling. Marinade that touched raw pork cooks in the pan and is then boiled for the sauce. Refrigerate leftovers in shallow containers within 2 hours and use within 3–4 days; reheat to 74 °C. Freeze for up to 2 months.</p>","author":"Néstor Bastidas","category":"Main dishes","cuisine":"Colombian","difficulty":"Intermediate","servings":12,"public_path":"/en/receta/colombian-roast-pork-leg-pernil","prep_time_minutes":25,"cook_time_minutes":245,"marinate_time_minutes":720,"rest_time_minutes":30,"total_time_minutes":1020,"nutrition":{"calories":661.1,"protein_g":44.3,"carbs_g":6.1,"fat_g":49.9,"serving_size":"1 of 12 portions with sauce","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Sum of raw-ingredient nutrients using USDA profiles, divided by the servings; juice is approximated as 1 g per ml.","note":"Estimate for 1 of 12 portions, dividing all the sauce equally, without sides. Uses a pork-leg profile including lean and fat; all fat and marinade are counted without deducting pan fat removed, so the served portion may be overestimated. Bay leaves are excluded."},"excerpt":"A Colombian December centerpiece: pork leg marinated overnight with citrus, garlic, onion and cumin. Covered roasting keeps the meat juicy before a final blast of heat browns the outside.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","course":"Main dishes","keywords":["Colombian Roast Pork Leg (Pernil)"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/ingredientes.webp","alt":"Colombian Roast Pork Leg (Pernil)"}]},{"language":"de","slug":"kolumbianische-schweinekeule-pernil","title":"Kolumbianische Schweinekeule aus dem Ofen","seo":{"title":"Kolumbianische Schweinekeule aus dem Ofen","description":"Pernil auf kolumbianische Art: Schweinekeule über Nacht mit Zitrus und Knoblauch marinieren, langsam garen und goldbraun rösten. Mit Kerntemperatur.","faq":[{"q":"Darf die Keule 24 Stunden marinieren?","a":"Ja. Zugedeckt bei höchstens 4 °C lagern und vor Ablauf von 24 Stunden Marinierzeit braten."},{"q":"Geht eine Keule mit Knochen?","a":"Ja, aber essbarer Ertrag und Garzeit ändern sich. Berechnet ist das Rezept für 3 kg ohne Knochen; an mehreren Stellen messen, ohne den Knochen zu berühren."},{"q":"Wie bleibt das Fleisch saftig?","a":"Flüssigkeit im Bräter halten, beim langsamen Garen dicht abdecken und die Kerntemperatur prüfen. Vor dem Schneiden 30 Minuten ruhen lassen."}],"image_alt":"Kolumbianische Schweinekeule aus dem Ofen","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-16x9.webp"],"additional_time_minutes":750},"summary":"Ein Festessen für den kolumbianischen Dezember: Schweinekeule zieht über Nacht in Zitrus, Knoblauch, Zwiebel und Kreuzkümmel. Zugedeckt bleibt sie saftig, zum Schluss wird sie bei hoher Hitze gebräunt.","ingredients":[{"amount":"3000","unit":"g","name":"Schweinekeule ohne Knochen und Schwarte, mit dünner Fettschicht, ein ganzes Stück, nicht gerollt"},{"amount":"200","unit":"g","name":"geschälte weiße Zwiebel"},{"amount":"40","unit":"g","name":"geschälter Knoblauch"},{"amount":"300","unit":"ml","name":"frisch gepresster Orangensaft"},{"amount":"60","unit":"ml","name":"frisch gepresster Limettensaft"},{"amount":"30","unit":"g","name":"Pflanzenöl"},{"amount":"30","unit":"g","name":"Salz"},{"amount":"4","unit":"g","name":"gemahlener Kreuzkümmel"},{"amount":"3","unit":"g","name":"getrockneter Oregano"},{"amount":"2","unit":"g","name":"gemahlener schwarzer Pfeffer"},{"amount":"2","unit":"Stück","name":"getrocknete Lorbeerblätter"},{"amount":"400","unit":"ml","name":"Wasser für den Bräter"}],"steps":[{"title":"Fleisch trocknen","content":"Die 3000 g Schweinekeule mit Küchenpapier trocken tupfen; nicht abwaschen."},{"title":"Marinade pürieren","content":"200 g Zwiebel, 40 g Knoblauch, 300 ml Orangensaft, 60 ml Limettensaft, 30 g Öl, 30 g Salz, 4 g Kreuzkümmel, 3 g Oregano und 2 g Pfeffer pürieren.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-02.webp","image_alt":"Marinade pürieren"},{"title":"Fleisch marinieren","content":"Die Keule in einem tiefen Behälter rundum mit der Marinade bestreichen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-03.webp","image_alt":"Fleisch marinieren"},{"title":"Lorbeer zugeben","content":"Die 2 Lorbeerblätter neben das Fleisch legen."},{"title":"Behälter schließen","content":"Den Behälter dicht verschließen, damit nichts ausläuft oder andere Lebensmittel berührt."},{"title":"Kühl stellen","content":"Die Keule 12 Stunden bei höchstens 4 °C kühlen."},{"title":"Ofen vorheizen","content":"Den Ofen auf 165 °C Ober- und Unterhitze ohne Umluft vorheizen."},{"title":"Fleisch einlegen","content":"Keule und gesamte Marinade in einen tiefen Bräter geben, Fettseite nach oben."},{"title":"Wasser zugießen","content":"Die 400 ml Wasser um das Fleisch herum angießen."},{"title":"Bräter abdecken","content":"Den Bräter mit backofengeeigneter Alufolie dicht verschließen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-10.webp","image_alt":"Bräter abdecken"},{"title":"Langsam braten","content":"Zugedeckt bei 165 °C 3 Stunden garen; etwas Flüssigkeit im Bräter halten und bei Bedarf zusätzlich heißes Wasser zugeben."},{"title":"Kerntemperatur prüfen","content":"Die dickste Stelle ohne Kontakt zum Bräter messen: Vor dem Bräunen sind mindestens 63 °C nötig; sonst zugedeckt jeweils 15 Minuten weitergaren, ungefähr bis zu 1 Stunde zusätzlich einplanen."},{"title":"Folie entfernen","content":"Die Folie vorsichtig abnehmen; auf heißen Dampf achten."},{"title":"Braten begießen","content":"Die Oberfläche mit heißem Bratensaft begießen."},{"title":"Hitze erhöhen","content":"Die Ofentemperatur auf 220 °C erhöhen."},{"title":"Keule bräunen","content":"Offen 20–30 Minuten goldbraun rösten; nur zu dunkel werdende Stellen abdecken.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-16.webp","image_alt":"Keule bräunen"},{"title":"Temperatur kontrollieren","content":"Mehrere dicke Stellen messen: Für dieses Rezept 68–72 °C anstreben; für ganzes Schweinefleisch gelten mindestens 63 °C und danach mindestens 3 Minuten Ruhezeit.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-17.webp","image_alt":"Temperatur kontrollieren"},{"title":"Aufs Brett legen","content":"Die Keule auf ein Schneidebrett mit Saftrinne legen."},{"title":"Locker abdecken","content":"Folie locker auf die Keule legen, ohne sie dicht einzuschließen."},{"title":"Ruhen lassen","content":"Vor dem Aufschneiden 30 Minuten ruhen lassen."},{"title":"Lorbeer entfernen","content":"Die 2 Lorbeerblätter aus dem Bratensaft entfernen."},{"title":"Bratensaft entfetten","content":"Das Fett vom Bratensaft abschöpfen."},{"title":"Sauce aufkochen","content":"Den entfetteten Bratensaft in einem kleinen Topf 5 Minuten sprudelnd kochen."},{"title":"Aufschneiden","content":"Quer zur Faser in Scheiben schneiden und in 12 Portionen teilen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-24.webp","image_alt":"Aufschneiden"},{"title":"Servieren","content":"Das Fleisch mit der heißen Sauce servieren.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","image_alt":"Kolumbianische Schweinekeule aus dem Ofen"}],"notes":"<p>Die Zeiten gelten für eine ganze, nicht gerollte Keule von 3 kg ohne Knochen, Schwarte oder Füllung, etwa 12–14 cm dick. Mit 3 Stunden 20 Minuten bis 4 Stunden 30 Minuten im Ofen rechnen; das Thermometer entscheidet. Das Fleisch für diese Methode nicht einstechen oder injizieren. Die Sicherheitsgrenze beträgt 63 °C plus 3 Minuten Ruhezeit; für diesen Scheibenbraten sind keine 90 °C nötig. Ohne Schwarte entsteht keine knusprige Schwarte, sondern eine gebräunte Fleisch- und Fettschicht. Die rohe Marinade gart im Bräter mit und wird für die Sauce zusätzlich gekocht. Reste innerhalb von 2 Stunden in flachen Behältern kühlen, in 3–4 Tagen verbrauchen und auf 74 °C erhitzen. Bis zu 2 Monate einfrieren.</p>","author":"Néstor Bastidas","category":"Hauptgerichte","cuisine":"Kolumbianisch","difficulty":"Mittel","servings":12,"public_path":"/de/receta/kolumbianische-schweinekeule-pernil","prep_time_minutes":25,"cook_time_minutes":245,"marinate_time_minutes":720,"rest_time_minutes":30,"total_time_minutes":1020,"nutrition":{"calories":661.1,"protein_g":44.3,"carbs_g":6.1,"fat_g":49.9,"serving_size":"1 von 12 Portionen mit Sauce","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Nährstoffe der rohen Zutaten nach USDA-Profilen summiert und durch die Portionenzahl geteilt; Saft mit 1 g je ml angenähert.","note":"Schätzung für 1 von 12 Portionen mit gleichmäßig verteilter gesamter Sauce, ohne Beilagen. Berechnet mit Keule samt Fleisch und Fett; entferntes Bratfett wird nicht abgezogen, daher kann die servierte Portion niedriger liegen. Lorbeerblätter sind nicht enthalten."},"excerpt":"Ein Festessen für den kolumbianischen Dezember: Schweinekeule zieht über Nacht in Zitrus, Knoblauch, Zwiebel und Kreuzkümmel. Zugedeckt bleibt sie saftig, zum Schluss wird sie bei hoher Hitze gebräunt.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","course":"Hauptgerichte","keywords":["Kolumbianische Schweinekeule aus dem Ofen"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/ingredientes.webp","alt":"Kolumbianische Schweinekeule aus dem Ofen"}]},{"language":"fr","slug":"cuisse-de-porc-rotie-pernil","title":"Pernil : cuisse de porc rôtie à la colombienne","seo":{"title":"Pernil : cuisse de porc rôtie à la colombienne","description":"Préparez un pernil colombien mariné dès la veille aux agrumes et à l’ail, puis rôti lentement au four, avec finition dorée et température à cœur.","faq":[{"q":"Peut-on laisser mariner 24 heures ?","a":"Oui. Gardez la viande couverte à 4 °C maximum et enfournez avant de dépasser 24 heures de marinade."},{"q":"Peut-on prendre une cuisse avec os ?","a":"Oui, mais le rendement et le temps changent. La recette est calculée pour 3 kg désossés ; mesurez plusieurs points sans toucher l’os."},{"q":"Comment garder une viande juteuse ?","a":"Maintenez du liquide dans le plat, couvrez hermétiquement pendant la cuisson lente et contrôlez la température. Respectez les 30 minutes de repos avant de trancher."}],"image_alt":"Pernil : cuisse de porc rôtie à la colombienne","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-16x9.webp"],"additional_time_minutes":750},"summary":"Un plat de fête du mois de décembre en Colombie : la cuisse de porc marine une nuit avec agrumes, ail, oignon et cumin. La cuisson couverte préserve son jus, puis une chaleur vive fait dorer la surface.","ingredients":[{"amount":"3000","unit":"g","name":"cuisse de porc désossée sans couenne, fine couche de gras conservée, en un seul morceau non roulé"},{"amount":"200","unit":"g","name":"oignon blanc épluché"},{"amount":"40","unit":"g","name":"ail épluché"},{"amount":"300","unit":"ml","name":"jus d’orange fraîchement pressé"},{"amount":"60","unit":"ml","name":"jus de citron vert fraîchement pressé"},{"amount":"30","unit":"g","name":"huile végétale"},{"amount":"30","unit":"g","name":"sel"},{"amount":"4","unit":"g","name":"cumin moulu"},{"amount":"3","unit":"g","name":"origan séché"},{"amount":"2","unit":"g","name":"poivre noir moulu"},{"amount":"2","unit":"pièce","name":"feuilles de laurier séchées"},{"amount":"400","unit":"ml","name":"eau pour le plat"}],"steps":[{"title":"Séchez le porc","content":"Séchez les 3000 g de cuisse avec du papier absorbant, sans la laver."},{"title":"Mixez la marinade","content":"Mixez 200 g d’oignon, 40 g d’ail, 300 ml de jus d’orange, 60 ml de jus de citron vert, 30 g d’huile, 30 g de sel, 4 g de cumin, 3 g d’origan et 2 g de poivre.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-02.webp","image_alt":"Mixez la marinade"},{"title":"Enrobez la viande","content":"Enrobez toute la cuisse de marinade dans un récipient profond.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-03.webp","image_alt":"Enrobez la viande"},{"title":"Ajoutez le laurier","content":"Placez les 2 feuilles de laurier à côté de la viande."},{"title":"Fermez le récipient","content":"Fermez hermétiquement pour éviter les fuites et tout contact avec d’autres aliments."},{"title":"Réfrigérez","content":"Laissez la viande au réfrigérateur à 4 °C maximum pendant 12 heures."},{"title":"Préchauffez le four","content":"Chauffez le four à 165 °C en chaleur statique, sans ventilation."},{"title":"Placez la cuisse","content":"Déposez la cuisse et toute la marinade dans un plat profond, gras vers le haut."},{"title":"Ajoutez l’eau","content":"Versez les 400 ml d’eau autour de la viande."},{"title":"Couvrez le plat","content":"Fermez soigneusement le plat avec du papier aluminium adapté au four.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-10.webp","image_alt":"Couvrez le plat"},{"title":"Faites rôtir doucement","content":"Cuisez à couvert à 165 °C pendant 3 heures ; gardez un fond de liquide avec un peu d’eau chaude supplémentaire si nécessaire."},{"title":"Contrôlez le cœur","content":"Mesurez la partie la plus épaisse sans toucher le plat : il faut au moins 63 °C avant le dorage ; sinon, poursuivez à couvert par tranches de 15 minutes, en prévoyant environ 1 heure supplémentaire au maximum."},{"title":"Découvrez","content":"Retirez l’aluminium avec précaution, en évitant la vapeur."},{"title":"Arrosez","content":"Arrosez la surface avec le jus chaud du plat."},{"title":"Augmentez la chaleur","content":"Réglez le four sur 220 °C."},{"title":"Faites dorer","content":"Rôtissez à découvert 20–30 minutes jusqu’à coloration dorée ; protégez seulement les zones qui foncent trop vite.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-16.webp","image_alt":"Faites dorer"},{"title":"Vérifiez la température","content":"Mesurez plusieurs zones épaisses : visez 68–72 °C pour cette recette ; le minimum de sécurité pour une pièce entière de porc est de 63 °C suivi d’au moins 3 minutes de repos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-17.webp","image_alt":"Vérifiez la température"},{"title":"Posez sur une planche","content":"Transférez la cuisse sur une planche à découper avec rigole."},{"title":"Couvrez légèrement","content":"Posez une feuille d’aluminium sans serrer ni fermer autour de la viande."},{"title":"Laissez reposer","content":"Laissez reposer 30 minutes avant de découper."},{"title":"Retirez le laurier","content":"Retirez les 2 feuilles de laurier du jus."},{"title":"Dégraissez le jus","content":"Retirez le gras à la surface du jus."},{"title":"Faites bouillir la sauce","content":"Faites bouillir le jus dégraissé dans une petite casserole pendant 5 minutes."},{"title":"Découpez","content":"Coupez en tranches perpendiculaires aux fibres pour obtenir 12 portions.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-24.webp","image_alt":"Découpez"},{"title":"Servez","content":"Servez le porc avec sa sauce chaude.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","image_alt":"Pernil : cuisse de porc rôtie à la colombienne"}],"notes":"<p>Les temps concernent une cuisse entière de 3 kg, désossée, non roulée, sans couenne ni farce, d’environ 12–14 cm d’épaisseur. Prévoyez 3 h 20 à 4 h 30 au four ; le thermomètre détermine la fin de cuisson. Ne piquez pas la viande et n’injectez pas de marinade pour cette méthode. Le seuil de sécurité de 63 °C suivi de 3 minutes de repos ne nécessite pas d’atteindre 90 °C : ce rôti se sert en tranches. Sans couenne, on obtient une surface dorée, pas une couenne croustillante. La marinade ayant touché le porc cru cuit dans le plat puis bout dans la sauce. Réfrigérez les restes dans des récipients peu profonds avant 2 heures et consommez-les sous 3–4 jours ; réchauffez à 74 °C. Congélation possible jusqu’à 2 mois.</p>","author":"Néstor Bastidas","category":"Plats principaux","cuisine":"Colombienne","difficulty":"Intermédiaire","servings":12,"public_path":"/fr/receta/cuisse-de-porc-rotie-pernil","prep_time_minutes":25,"cook_time_minutes":245,"marinate_time_minutes":720,"rest_time_minutes":30,"total_time_minutes":1020,"nutrition":{"calories":661.1,"protein_g":44.3,"carbs_g":6.1,"fat_g":49.9,"serving_size":"1 des 12 portions avec sauce","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Somme des nutriments des ingrédients crus selon les profils USDA, divisée par le nombre de portions ; jus estimé à 1 g par ml.","note":"Estimation pour 1 des 12 portions avec toute la sauce répartie, sans accompagnement. Profil de cuisse comprenant viande et gras ; le gras retiré du plat n’est pas déduit, ce qui peut surestimer la portion servie. Laurier exclu."},"excerpt":"Un plat de fête du mois de décembre en Colombie : la cuisse de porc marine une nuit avec agrumes, ail, oignon et cumin. La cuisson couverte préserve son jus, puis une chaleur vive fait dorer la surface.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","course":"Plats principaux","keywords":["Pernil : cuisse de porc rôtie à la colombienne"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/ingredientes.webp","alt":"Pernil : cuisse de porc rôtie à la colombienne"}]},{"language":"it","slug":"coscia-di-maiale-al-forno-pernil","title":"Pernil: coscia di maiale al forno alla colombiana","seo":{"title":"Pernil: coscia di maiale al forno alla colombiana","description":"Prepara il pernil colombiano con marinata di agrumi e aglio dalla sera prima, cottura lenta al forno e doratura finale. Con tempi e temperatura al cuore.","faq":[{"q":"Posso marinare per 24 ore?","a":"Sì. Tieni la carne coperta a 4 °C o meno e inforna prima di superare 24 ore di marinatura."},{"q":"Posso usare una coscia con osso?","a":"Sì, ma resa e tempi cambiano. La ricetta è calcolata per 3 kg senza osso; misura più punti evitando l’osso."},{"q":"Come evito che si asciughi?","a":"Mantieni liquido nella teglia, copri bene durante la cottura lenta e controlla la temperatura. Rispetta i 30 minuti di riposo prima di affettare."}],"image_alt":"Pernil: coscia di maiale al forno alla colombiana","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-16x9.webp"],"additional_time_minutes":750},"summary":"Un arrosto delle feste di dicembre in Colombia: la coscia di maiale riposa una notte con agrumi, aglio, cipolla e cumino. La cottura coperta trattiene i succhi, poi il calore alto dora la superficie.","ingredients":[{"amount":"3000","unit":"g","name":"coscia di maiale disossata, senza cotenna e con un sottile strato di grasso, in un pezzo intero non arrotolato"},{"amount":"200","unit":"g","name":"cipolla bianca sbucciata"},{"amount":"40","unit":"g","name":"aglio sbucciato"},{"amount":"300","unit":"ml","name":"succo d’arancia appena spremuto"},{"amount":"60","unit":"ml","name":"succo di lime appena spremuto"},{"amount":"30","unit":"g","name":"olio vegetale"},{"amount":"30","unit":"g","name":"sale"},{"amount":"4","unit":"g","name":"cumino macinato"},{"amount":"3","unit":"g","name":"origano secco"},{"amount":"2","unit":"g","name":"pepe nero macinato"},{"amount":"2","unit":"pezzo","name":"foglie di alloro secche"},{"amount":"400","unit":"ml","name":"acqua per la teglia"}],"steps":[{"title":"Asciuga la carne","content":"Asciuga i 3000 g di coscia con carta da cucina, senza lavarla."},{"title":"Frulla la marinata","content":"Frulla 200 g di cipolla, 40 g di aglio, 300 ml di succo d’arancia, 60 ml di succo di lime, 30 g d’olio, 30 g di sale, 4 g di cumino, 3 g di origano e 2 g di pepe.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-02.webp","image_alt":"Frulla la marinata"},{"title":"Condisci la coscia","content":"Rivesti tutta la coscia con la marinata in un contenitore profondo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-03.webp","image_alt":"Condisci la coscia"},{"title":"Aggiungi l’alloro","content":"Disponi le 2 foglie di alloro accanto alla carne."},{"title":"Chiudi il contenitore","content":"Chiudi bene per evitare perdite e contatti con altri alimenti."},{"title":"Metti in frigorifero","content":"Lascia la carne in frigorifero a 4 °C o meno per 12 ore."},{"title":"Scalda il forno","content":"Scalda il forno statico a 165 °C, senza ventilazione."},{"title":"Sistema la coscia","content":"Trasferisci coscia e marinata in una teglia profonda, con il grasso verso l’alto."},{"title":"Aggiungi l’acqua","content":"Versa i 400 ml d’acqua intorno alla carne."},{"title":"Copri la teglia","content":"Sigilla bene la teglia con alluminio adatto al forno.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-10.webp","image_alt":"Copri la teglia"},{"title":"Cuoci lentamente","content":"Cuoci coperto a 165 °C per 3 ore; mantieni un fondo di liquido con altra acqua calda se necessario."},{"title":"Controlla il cuore","content":"Misura la parte più spessa senza toccare la teglia: prima della doratura deve raggiungere almeno 63 °C; altrimenti prosegui coperto per intervalli di 15 minuti, prevedendo indicativamente fino a 1 ora in più."},{"title":"Scopri la teglia","content":"Rimuovi l’alluminio con attenzione al vapore."},{"title":"Bagna la carne","content":"Irrora la superficie con il fondo caldo della teglia."},{"title":"Alza la temperatura","content":"Porta il forno a 220 °C."},{"title":"Fai dorare","content":"Cuoci scoperto per 20–30 minuti fino a doratura; proteggi solo le parti che scuriscono troppo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-16.webp","image_alt":"Fai dorare"},{"title":"Verifica la temperatura","content":"Misura più punti spessi: per questa ricetta punta a 68–72 °C; il minimo sicuro per il maiale intero è 63 °C seguito da almeno 3 minuti di riposo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-17.webp","image_alt":"Verifica la temperatura"},{"title":"Trasferisci sul tagliere","content":"Sposta la coscia su un tagliere con scanalatura per i succhi."},{"title":"Copri leggermente","content":"Appoggia un foglio di alluminio senza sigillare la carne."},{"title":"Lascia riposare","content":"Lascia riposare per 30 minuti prima del taglio."},{"title":"Togli l’alloro","content":"Elimina le 2 foglie di alloro dal fondo."},{"title":"Sgrassa il fondo","content":"Elimina il grasso in superficie dal fondo della teglia."},{"title":"Fai bollire la salsa","content":"Fai bollire il fondo sgrassato in un pentolino per 5 minuti."},{"title":"Affetta","content":"Taglia controfibra in fette da suddividere in 12 porzioni.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-24.webp","image_alt":"Affetta"},{"title":"Servi","content":"Servi il maiale con la salsa calda.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","image_alt":"Pernil: coscia di maiale al forno alla colombiana"}],"notes":"<p>I tempi si riferiscono a una coscia intera di 3 kg, disossata, non arrotolata, senza cotenna o ripieno, spessa circa 12–14 cm. Prevedi 3 ore e 20 minuti–4 ore e 30 minuti di forno: il termometro determina il termine della cottura. Non bucare né iniettare la carne con questo metodo. La soglia di sicurezza è 63 °C con 3 minuti di riposo; per un arrosto da affettare non occorre arrivare a 90 °C. Senza cotenna si ottiene una superficie dorata di carne e grasso. La marinata a contatto con la carne cruda cuoce nella teglia e poi bolle nella salsa. Conserva gli avanzi in frigorifero in contenitori bassi entro 2 ore; consumali in 3–4 giorni e riscaldali a 74 °C. Puoi congelarli fino a 2 mesi.</p>","author":"Néstor Bastidas","category":"Secondi piatti","cuisine":"Colombiana","difficulty":"Media","servings":12,"public_path":"/it/receta/coscia-di-maiale-al-forno-pernil","prep_time_minutes":25,"cook_time_minutes":245,"marinate_time_minutes":720,"rest_time_minutes":30,"total_time_minutes":1020,"nutrition":{"calories":661.1,"protein_g":44.3,"carbs_g":6.1,"fat_g":49.9,"serving_size":"1 delle 12 porzioni con salsa","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Somma dei nutrienti degli ingredienti crudi secondo profili USDA, divisa per le porzioni; i succhi sono approssimati a 1 g per ml.","note":"Stima per 1 delle 12 porzioni con tutta la salsa distribuita, senza contorni. Usa un profilo di coscia con carne e grasso; il grasso eliminato dalla teglia non viene sottratto, quindi la porzione servita può avere valori inferiori. Alloro escluso."},"excerpt":"Un arrosto delle feste di dicembre in Colombia: la coscia di maiale riposa una notte con agrumi, aglio, cipolla e cumino. La cottura coperta trattiene i succhi, poi il calore alto dora la superficie.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","course":"Secondi piatti","keywords":["Pernil: coscia di maiale al forno alla colombiana"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/ingredientes.webp","alt":"Pernil: coscia di maiale al forno alla colombiana"}]},{"language":"ja","slug":"pernil-buta-momo-oven-yaki","title":"コロンビア風豚もも肉のオーブン焼き・ペルニル","seo":{"title":"コロンビア風豚もも肉のオーブン焼き・ペルニル","description":"コロンビアの12月のごちそう、豚もも肉のペルニル。前夜からオレンジ、ライム、にんにくのたれに漬け、オーブンでじっくり焼き上げます。ふたをして肉汁を守る焼き方から、表面を香ばしく仕上げる温度、中心温度の測り方、切る前の休ませ方まで紹介する12人分のレシピです。","faq":[{"q":"24時間漬けてもよいですか？","a":"ふたをして4 °C以下で保管すれば可能です。漬け始めてから24時間を超える前に焼いてください。"},{"q":"骨付き肉でも作れますか？","a":"作れますが、可食部の量と焼き時間が変わります。このレシピは骨なし3 kg用です。骨に触れない数か所で温度を確認してください。"},{"q":"しっとり仕上げるには？","a":"天板に汁を保ち、低温で焼く間はしっかり覆います。中心温度を測り、切る前に30分休ませてください。"}],"image_alt":"コロンビア風豚もも肉のオーブン焼き・ペルニル","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-16x9.webp"],"additional_time_minutes":750},"summary":"コロンビアの年末の食卓を彩る、大きな豚もも肉のロースト。前夜から柑橘、にんにく、玉ねぎ、クミンで味をつけ、覆ってじっくり焼いた後、高温で香ばしい焼き色をつけます。","ingredients":[{"amount":"3000","unit":"g","name":"豚もも肉（骨・皮なし、薄い脂肪を残したひと塊、巻いていないもの）"},{"amount":"200","unit":"g","name":"白玉ねぎ（皮をむいたもの）"},{"amount":"40","unit":"g","name":"にんにく（皮をむいたもの）"},{"amount":"300","unit":"ml","name":"搾りたてのオレンジ果汁"},{"amount":"60","unit":"ml","name":"搾りたてのライム果汁"},{"amount":"30","unit":"g","name":"植物油"},{"amount":"30","unit":"g","name":"塩"},{"amount":"4","unit":"g","name":"クミンパウダー"},{"amount":"3","unit":"g","name":"ドライオレガノ"},{"amount":"2","unit":"g","name":"粗びき黒こしょう"},{"amount":"2","unit":"個","name":"乾燥ローリエ"},{"amount":"400","unit":"ml","name":"天板用の水"}],"steps":[{"title":"肉の水気を拭く","content":"豚もも肉3000 gの水気をキッチンペーパーで拭きます。水洗いはしません。"},{"title":"たれをかくはんする","content":"玉ねぎ200 g、にんにく40 g、オレンジ果汁300 ml、ライム果汁60 ml、油30 g、塩30 g、クミン4 g、オレガノ3 g、黒こしょう2 gをミキサーにかけます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-02.webp","image_alt":"たれをかくはんする"},{"title":"肉にたれをからめる","content":"深い容器に肉を入れ、全体に漬けだれをからめます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-03.webp","image_alt":"肉にたれをからめる"},{"title":"ローリエを加える","content":"ローリエ2枚を肉の横に入れます。"},{"title":"ふたをする","content":"汁漏れやほかの食品との接触を防ぐため、容器を密閉します。"},{"title":"冷蔵する","content":"4 °C以下の冷蔵庫で12時間漬けます。"},{"title":"オーブンを予熱する","content":"オーブンを165 °Cに予熱します。上下加熱を使い、熱風機能は切ります。"},{"title":"天板に移す","content":"深い天板に肉と漬けだれを全量移し、脂の面を上にします。"},{"title":"水を加える","content":"肉の周りに水400 mlを注ぎます。"},{"title":"天板を覆う","content":"オーブン対応のアルミホイルで天板を隙間なく覆います。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-10.webp","image_alt":"天板を覆う"},{"title":"じっくり焼く","content":"165 °Cで覆ったまま3時間焼きます。底に汁が残るよう、必要に応じて分量外の湯を補います。"},{"title":"中心を測る","content":"天板に触れないよう最も厚い部分を測り、焼き色をつける前に63 °C以上にします。不足する場合は覆ったまま15分ずつ追加し、目安として最大約1時間の追加を見込みます。"},{"title":"覆いを外す","content":"蒸気に気をつけてアルミホイルを外します。"},{"title":"肉汁をかける","content":"天板の熱い肉汁を肉の表面にかけます。"},{"title":"温度を上げる","content":"オーブンを220 °Cに設定します。"},{"title":"焼き色をつける","content":"覆わずに20〜30分焼き、こんがり色づけます。濃くなりすぎる部分だけホイルで保護します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-16.webp","image_alt":"焼き色をつける"},{"title":"温度を確認する","content":"厚い部分を数か所測り、この料理では68〜72 °Cを目安にします。豚の塊肉の安全上の最低温度は63 °Cで、その後3分以上休ませます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-17.webp","image_alt":"温度を確認する"},{"title":"まな板に移す","content":"肉汁を受ける溝のあるまな板に肉を移します。"},{"title":"軽く覆う","content":"アルミホイルをふんわりかけ、密閉しないようにします。"},{"title":"休ませる","content":"切る前に30分休ませます。"},{"title":"ローリエを除く","content":"肉汁からローリエ2枚を取り除きます。"},{"title":"肉汁の脂を除く","content":"天板の肉汁に浮いた脂を取り除きます。"},{"title":"ソースを煮立てる","content":"脂を除いた肉汁を小鍋で5分沸騰させます。"},{"title":"肉を切る","content":"繊維を断つ向きに薄切りにし、12人分に分けます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-24.webp","image_alt":"肉を切る"},{"title":"盛り付ける","content":"温かいソースを添えて盛り付けます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","image_alt":"コロンビア風豚もも肉のオーブン焼き・ペルニル"}],"notes":"<p>骨、皮、詰め物がなく、巻いていない3 kg、厚さ約12〜14 cmの塊肉を想定しています。焼き時間は3時間20分〜4時間30分が目安で、最後は温度計で判断します。この方法では肉に穴を開けたり、たれを注入したりしません。63 °Cと3分の休みが安全上の最低基準です。薄切りで味わう料理なので90 °Cまで上げる必要はありません。皮なしのため、皮をパリパリにする仕上がりではなく、肉と脂に焼き色をつけます。生肉に触れたたれは天板で加熱し、さらにソースとして沸騰させます。残りは2時間以内に浅い容器で冷蔵し、3〜4日で食べ切り、再加熱は74 °Cまで。冷凍は最長2か月です。</p>","author":"Néstor Bastidas","category":"主菜","cuisine":"コロンビア料理","difficulty":"中級","servings":12,"public_path":"/ja/receta/pernil-buta-momo-oven-yaki","prep_time_minutes":25,"cook_time_minutes":245,"marinate_time_minutes":720,"rest_time_minutes":30,"total_time_minutes":1020,"nutrition":{"calories":661.1,"protein_g":44.3,"carbs_g":6.1,"fat_g":49.9,"serving_size":"ソース付き1人分（全12人分）","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"USDAの食品成分値で生の材料の栄養量を合計し、人数で割った推定値です。果汁は1 mlを1 gとして計算しています。","note":"12人分のうち1人分、ソース全量を均等に分け、付け合わせを除いた推定値です。脂を含む豚もも肉の成分を使い、取り除いた脂や残ったたれは差し引いていないため、実際より高めになる場合があります。ローリエは含みません。"},"excerpt":"コロンビアの年末の食卓を彩る、大きな豚もも肉のロースト。前夜から柑橘、にんにく、玉ねぎ、クミンで味をつけ、覆ってじっくり焼いた後、高温で香ばしい焼き色をつけます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","course":"主菜","keywords":["コロンビア風豚もも肉のオーブン焼き・ペルニル"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/ingredientes.webp","alt":"コロンビア風豚もも肉のオーブン焼き・ペルニル"}]},{"language":"pt","slug":"pernil-de-porco-assado","title":"Pernil de porco assado à colombiana","seo":{"title":"Pernil de porco assado à colombiana","description":"Faça pernil de porco à colombiana com marinada de véspera, cítricos e alho. Assado lento, dourado por fora, com tempo de forno e temperatura interna.","faq":[{"q":"Posso marinar por 24 horas?","a":"Sim. Mantenha a peça tampada a 4 °C ou menos e asse antes de ultrapassar 24 horas de marinada."},{"q":"Posso usar pernil com osso?","a":"Sim, mas o rendimento e o tempo mudam. Esta receita foi calculada para 3 kg sem osso; confira vários pontos sem encostar no osso."},{"q":"Como evitar que fique seco?","a":"Mantenha líquido na assadeira, cubra bem durante a cocção lenta e meça a temperatura. Respeite os 30 minutos de descanso antes de fatiar."}],"image_alt":"Pernil de porco assado à colombiana","author":"Néstor Bastidas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada-16x9.webp"],"additional_time_minutes":750},"summary":"Um pernil para a mesa de dezembro na Colômbia: a carne passa a noite em uma marinada de cítricos, alho, cebola e cominho. O forno coberto preserva os sucos, e o calor alto no final deixa a superfície dourada.","ingredients":[{"amount":"3000","unit":"g","name":"pernil suíno sem osso e sem pele, com fina camada de gordura, em peça única sem enrolar"},{"amount":"200","unit":"g","name":"cebola branca descascada"},{"amount":"40","unit":"g","name":"alho descascado"},{"amount":"300","unit":"ml","name":"suco de laranja espremido na hora"},{"amount":"60","unit":"ml","name":"suco de limão-taiti espremido na hora"},{"amount":"30","unit":"g","name":"óleo vegetal"},{"amount":"30","unit":"g","name":"sal"},{"amount":"4","unit":"g","name":"cominho em pó"},{"amount":"3","unit":"g","name":"orégano seco"},{"amount":"2","unit":"g","name":"pimenta-do-reino moída"},{"amount":"2","unit":"unidade","name":"folhas de louro secas"},{"amount":"400","unit":"ml","name":"água para a assadeira"}],"steps":[{"title":"Seque o pernil","content":"Seque os 3000 g de pernil com papel-toalha, sem lavar a carne."},{"title":"Bata a marinada","content":"Bata no liquidificador 200 g de cebola, 40 g de alho, 300 ml de suco de laranja, 60 ml de suco de limão, 30 g de óleo, 30 g de sal, 4 g de cominho, 3 g de orégano e 2 g de pimenta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-02.webp","image_alt":"Bata a marinada"},{"title":"Tempere o pernil","content":"Envolva toda a peça na marinada dentro de um recipiente fundo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-03.webp","image_alt":"Tempere o pernil"},{"title":"Acrescente o louro","content":"Coloque as 2 folhas de louro ao lado da carne."},{"title":"Tampe o recipiente","content":"Feche bem para evitar vazamentos e contato com outros alimentos."},{"title":"Leve à geladeira","content":"Mantenha o pernil na geladeira a 4 °C ou menos por 12 horas."},{"title":"Preaqueça o forno","content":"Aqueça o forno a 165 °C, com calor superior e inferior, sem ventilação."},{"title":"Acomode o pernil","content":"Passe a carne e toda a marinada para uma assadeira funda, com a gordura para cima."},{"title":"Adicione a água","content":"Despeje os 400 ml de água ao redor da carne."},{"title":"Cubra a assadeira","content":"Feche bem a assadeira com papel-alumínio próprio para forno.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-10.webp","image_alt":"Cubra a assadeira"},{"title":"Asse lentamente","content":"Asse coberto a 165 °C por 3 horas; mantenha um pouco de líquido no fundo com água quente adicional se necessário."},{"title":"Confira o centro","content":"Meça a parte mais grossa sem tocar a assadeira: ela deve atingir pelo menos 63 °C antes de dourar; se necessário, continue coberto por intervalos de 15 minutos, prevendo aproximadamente até 1 hora adicional."},{"title":"Descubra","content":"Retire o alumínio com cuidado com o vapor."},{"title":"Regue a carne","content":"Regue a superfície com o caldo quente da assadeira."},{"title":"Aumente a temperatura","content":"Ajuste o forno para 220 °C."},{"title":"Doure o pernil","content":"Asse descoberto por 20–30 minutos, até dourar; proteja apenas as áreas que escurecerem demais.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-16.webp","image_alt":"Doure o pernil"},{"title":"Verifique a temperatura","content":"Meça vários pontos grossos: procure atingir 68–72 °C nesta receita; o mínimo seguro para uma peça inteira de porco é 63 °C seguido de pelo menos 3 minutos de descanso.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-17.webp","image_alt":"Verifique a temperatura"},{"title":"Passe para uma tábua","content":"Transfira o pernil para uma tábua com canaleta para os sucos."},{"title":"Cubra levemente","content":"Coloque o alumínio frouxo sobre o pernil, sem vedar."},{"title":"Deixe descansar","content":"Descanse por 30 minutos antes de cortar."},{"title":"Retire o louro","content":"Retire as 2 folhas de louro do caldo."},{"title":"Retire a gordura","content":"Retire a gordura da superfície do caldo da assadeira."},{"title":"Ferva o molho","content":"Ferva o caldo sem a gordura em uma panela pequena por 5 minutos."},{"title":"Fatie o pernil","content":"Corte em fatias contra as fibras e divida em 12 porções.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/paso-24.webp","image_alt":"Fatie o pernil"},{"title":"Sirva","content":"Sirva o pernil com o molho quente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","image_alt":"Pernil de porco assado à colombiana"}],"notes":"<p>Os tempos são para uma peça inteira de 3 kg, sem osso, pele ou recheio, sem enrolar, com cerca de 12–14 cm de espessura. Reserve 3 h 20 min–4 h 30 min de forno; o termômetro determina o ponto. Não fure nem injete a carne neste método. O mínimo de segurança de 63 °C com 3 minutos de descanso não exige chegar a 90 °C: esta versão é para fatiar. Sem pele, o dourado fica na carne e na gordura, sem pururuca. A marinada que tocou a carne crua cozinha na assadeira e depois ferve no molho. Leve as sobras à geladeira em recipientes rasos em até 2 horas e consuma em 3–4 dias; reaqueça até 74 °C. Congele por até 2 meses.</p>","author":"Néstor Bastidas","category":"Pratos principais","cuisine":"Colombiana","difficulty":"Intermediária","servings":12,"public_path":"/pt/receta/pernil-de-porco-assado","prep_time_minutes":25,"cook_time_minutes":245,"marinate_time_minutes":720,"rest_time_minutes":30,"total_time_minutes":1020,"nutrition":{"calories":661.1,"protein_g":44.3,"carbs_g":6.1,"fat_g":49.9,"serving_size":"1 das 12 porções com molho","estimated":true,"source":"USDA FoodData Central / Standard Reference; generic ingredient profiles","method":"Soma dos nutrientes dos ingredientes crus com perfis USDA, dividida pelas porções; os sucos são aproximados como 1 g por ml.","note":"Estimativa para 1 das 12 porções com todo o molho dividido, sem acompanhamentos. Usa perfil de pernil com carne e gordura; não desconta a gordura retirada da assadeira, podendo superestimar a porção servida. Não inclui louro."},"excerpt":"Um pernil para a mesa de dezembro na Colômbia: a carne passa a noite em uma marinada de cítricos, alho, cebola e cominho. O forno coberto preserva os sucos, e o calor alto no final deixa a superfície dourada.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/portada.webp","course":"Pratos principais","keywords":["Pernil de porco assado à colombiana"],"content_html":"","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/pernil-de-cerdo-al-horno/ingredientes.webp","alt":"Pernil de porco assado à colombiana"}]}]$content$::jsonb;
 aliases jsonb := $aliases$[{"ingredient_id":"1d2b384c-fed9-4401-94e9-e0c9c58657cd","alias":"pierna de cerdo deshuesada, sin piel y con una capa fina de grasa, en una sola pieza sin enrollar"},{"ingredient_id":"c1d5ae46-ce64-4ca5-ae74-49201f626e14","alias":"cebolla blanca pelada"},{"ingredient_id":"75746b02-4b4c-4c2d-8751-04d3b2a24f0e","alias":"ajo pelado"},{"ingredient_id":"1a18305a-50ab-495f-aee7-acd77d158f26","alias":"jugo de naranja recién exprimido"},{"ingredient_id":"3c776029-8c68-4690-9054-23174803e9b1","alias":"jugo de limón recién exprimido"},{"ingredient_id":"cfb1e866-27fa-4e97-99ff-1af1527ac2b3","alias":"aceite vegetal"},{"ingredient_id":"adbdba3e-00c5-4a63-9140-6b0ae740d813","alias":"sal"},{"ingredient_id":"74d0a20e-32b8-4ebc-a434-88b566e72f3c","alias":"comino molido"},{"ingredient_id":"26e09506-1b5e-4356-8f67-9ebda5ccba6e","alias":"orégano seco"},{"ingredient_id":"2de4d4f2-8bb2-401b-9b88-a29427b8690b","alias":"pimienta negra molida"},{"ingredient_id":"05ce4acd-3e3a-4c86-af86-698af7d5145e","alias":"hojas de laurel secas"},{"ingredient_id":"6a189b14-0318-498f-9a7d-81fc2592be37","alias":"agua para la bandeja"}]$aliases$::jsonb;
 v_source uuid;
 v_group uuid;
 v_alias jsonb;
 v_n integer;
BEGIN
 IF EXISTS (SELECT 1 FROM public.recipes WHERE slug IN (SELECT x->>'slug' FROM jsonb_array_elements(payload) x))
 OR EXISTS (SELECT 1 FROM public.content_pages WHERE public_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x))
 OR EXISTS (SELECT 1 FROM public.content_redirects WHERE source_path IN (SELECT x->>'public_path' FROM jsonb_array_elements(payload) x)) THEN
 RAISE EXCEPTION 'A recipe or route already exists; review identity before publication'; END IF;
 IF EXISTS (SELECT 1 FROM public.ingredients WHERE slug='jugo-de-naranja' AND id<>'1a18305a-50ab-495f-aee7-acd77d158f26'::uuid) THEN RAISE EXCEPTION 'Orange juice identity changed'; END IF;
 UPDATE public.ingredients SET slug='jugo-de-naranja',name='Jugo de naranja',normalized_name='jugo de naranja',description='Jugo natural de naranja exprimida, sin azúcar añadido.',status='canonical',searchable=true,indexable=false WHERE id='1a18305a-50ab-495f-aee7-acd77d158f26'::uuid AND status IN ('pending','review') AND lower(name)='jugo de naranja';
 FOR v_alias IN SELECT x FROM jsonb_array_elements(aliases) x LOOP
  IF NOT EXISTS (SELECT 1 FROM public.ingredients WHERE id=(v_alias->>'ingredient_id')::uuid AND status='canonical' AND searchable) THEN RAISE EXCEPTION 'Missing canonical ingredient'; END IF;
  IF EXISTS (SELECT 1 FROM public.ingredient_aliases a JOIN public.ingredients i ON i.id=a.ingredient_id WHERE a.normalized_alias=lower(v_alias->>'alias') AND a.ingredient_id<>(v_alias->>'ingredient_id')::uuid AND i.status='canonical') THEN RAISE EXCEPTION 'Ingredient alias collision'; END IF;
  INSERT INTO public.ingredient_aliases (ingredient_id,alias,normalized_alias) VALUES ((v_alias->>'ingredient_id')::uuid,v_alias->>'alias',lower(v_alias->>'alias')) ON CONFLICT (ingredient_id,normalized_alias) DO NOTHING;
 END LOOP;
 INSERT INTO public.recipes (language, slug, title, excerpt, summary, ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url, content_html, notes, difficulty, course, cuisine, keywords, nutrition, seo, public_path, gallery,published,editorial_status)
 SELECT s.language, s.slug, s.title, s.excerpt, s.summary, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.total_time_minutes, s.servings, s.image_url, s.content_html, s.notes, s.difficulty, s.course, s.cuisine, s.keywords, s.nutrition, s.seo, s.public_path, s.gallery,false,'draft' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language='es'
 RETURNING id,recipe_group_id INTO v_source,v_group;
 INSERT INTO public.recipes (recipe_group_id,language, slug, title, excerpt, summary, ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url, content_html, notes, difficulty, course, cuisine, keywords, nutrition, seo, public_path, gallery,published,editorial_status)
 SELECT v_group,s.language, s.slug, s.title, s.excerpt, s.summary, s.ingredients, s.steps, s.category, s.prep_time_minutes, s.cook_time_minutes, s.total_time_minutes, s.servings, s.image_url, s.content_html, s.notes, s.difficulty, s.course, s.cuisine, s.keywords, s.nutrition, s.seo, s.public_path, s.gallery,false,'draft' FROM jsonb_populate_recordset(NULL::public.recipes,payload) s WHERE s.language<>'es';
 IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=v_source)<>12 OR EXISTS (SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=v_source) THEN RAISE EXCEPTION 'Ingredient catalogue mapping incomplete'; END IF;
 UPDATE public.recipes SET published=true,editorial_status='published' WHERE recipe_group_id=v_group;
 SELECT count(DISTINCT language) INTO v_n FROM public.recipes WHERE recipe_group_id=v_group AND published AND nutrition IS NOT NULL;
 IF v_n<>7 THEN RAISE EXCEPTION 'Incomplete seven-language publication'; END IF;
 RAISE NOTICE 'Published group % with seven languages',v_group;
END $publish$;
COMMIT;
